-- Ms. Lien English Center: core data model.
create extension if not exists pgcrypto;
create type public.app_role as enum ('teacher','student');
create type public.exercise_type as enum ('multiple_choice','fill_blank','essay','listening','speaking');
create table public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',role public.app_role not null default 'student',created_at timestamptz not null default now());
create table public.classrooms(id uuid primary key default gen_random_uuid(),name text not null,description text,teacher_id uuid not null references public.profiles(user_id) on delete restrict,created_at timestamptz not null default now());
create table public.class_members(classroom_id uuid not null references public.classrooms(id) on delete cascade,student_id uuid not null references public.profiles(user_id) on delete cascade,joined_at timestamptz not null default now(),primary key(classroom_id,student_id));
create table public.assignments(id uuid primary key default gen_random_uuid(),classroom_id uuid not null references public.classrooms(id) on delete cascade,title text not null,description text,due_at timestamptz,published boolean not null default true,created_by uuid not null references public.profiles(user_id),created_at timestamptz not null default now());
create table public.questions(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.assignments(id) on delete cascade,type public.exercise_type not null,prompt text not null,passage text,options jsonb not null default '[]'::jsonb,audio_path text,points integer not null default 1 check(points between 1 and 1000),sort_order integer not null default 0);
-- Answer keys are intentionally separate from questions and never selectable by students.
create table public.answer_keys(question_id uuid primary key references public.questions(id) on delete cascade,correct_answers jsonb not null default '[]'::jsonb);
create table public.submissions(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.assignments(id) on delete cascade,student_id uuid not null references public.profiles(user_id) on delete cascade,status text not null default 'submitted' check(status in ('submitted','graded')),score numeric,submitted_at timestamptz not null default now(),graded_at timestamptz,unique(assignment_id,student_id));
create table public.answers(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.submissions(id) on delete cascade,question_id uuid not null references public.questions(id) on delete cascade,response_text text,audio_path text,score numeric,feedback text,unique(submission_id,question_id));
create index assignments_classroom_idx on public.assignments(classroom_id,created_at desc);create index class_members_student_idx on public.class_members(student_id);create index submissions_student_idx on public.submissions(student_id,submitted_at desc);create index answers_submission_idx on public.answers(submission_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(user_id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''), 'student') on conflict(user_id) do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_teacher_of_class(_class uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.classrooms c join public.profiles p on p.user_id=c.teacher_id where c.id=_class and c.teacher_id=auth.uid() and p.role='teacher'); $$;
create or replace function public.is_member_of_class(_class uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.class_members m join public.profiles p on p.user_id=m.student_id where m.classroom_id=_class and m.student_id=auth.uid() and p.role='student'); $$;
alter table public.profiles enable row level security;alter table public.classrooms enable row level security;alter table public.class_members enable row level security;alter table public.assignments enable row level security;alter table public.questions enable row level security;alter table public.answer_keys enable row level security;alter table public.submissions enable row level security;alter table public.answers enable row level security;
create policy "profile self read" on public.profiles for select to authenticated using(user_id=auth.uid());
create policy "teacher reads class profiles" on public.profiles for select to authenticated using(role='student' and exists(select 1 from public.class_members m where m.student_id=profiles.user_id and public.is_teacher_of_class(m.classroom_id)));
create policy "teacher creates own classes" on public.classrooms for insert to authenticated with check(teacher_id=auth.uid() and exists(select 1 from public.profiles p where p.user_id=auth.uid() and p.role='teacher'));
create policy "teacher reads own classes" on public.classrooms for select to authenticated using(teacher_id=auth.uid() or public.is_member_of_class(id));
create policy "teacher updates own classes" on public.classrooms for update to authenticated using(teacher_id=auth.uid()) with check(teacher_id=auth.uid());
create policy "teacher deletes own classes" on public.classrooms for delete to authenticated using(teacher_id=auth.uid());
create policy "class roster visible to teacher and member" on public.class_members for select to authenticated using(public.is_teacher_of_class(classroom_id) or student_id=auth.uid());
create policy "teacher adds members" on public.class_members for insert to authenticated with check(public.is_teacher_of_class(classroom_id) and exists(select 1 from public.profiles p where p.user_id=student_id and p.role='student'));
create policy "teacher removes members" on public.class_members for delete to authenticated using(public.is_teacher_of_class(classroom_id));
create policy "assignment teacher or class students read" on public.assignments for select to authenticated using(public.is_teacher_of_class(classroom_id) or (published and public.is_member_of_class(classroom_id)));
create policy "teacher creates assignments" on public.assignments for insert to authenticated with check(created_by=auth.uid() and public.is_teacher_of_class(classroom_id));
create policy "teacher updates assignments" on public.assignments for update to authenticated using(public.is_teacher_of_class(classroom_id)) with check(public.is_teacher_of_class(classroom_id));
create policy "teacher deletes assignments" on public.assignments for delete to authenticated using(public.is_teacher_of_class(classroom_id));
create policy "questions teacher or assigned students read" on public.questions for select to authenticated using(exists(select 1 from public.assignments a where a.id=assignment_id and (public.is_teacher_of_class(a.classroom_id) or (a.published and public.is_member_of_class(a.classroom_id)))));
create policy "answer key teacher read only" on public.answer_keys for select to authenticated using(exists(select 1 from public.questions q join public.assignments a on a.id=q.assignment_id where q.id=question_id and public.is_teacher_of_class(a.classroom_id)));
create policy "submission student or teacher read" on public.submissions for select to authenticated using(student_id=auth.uid() or exists(select 1 from public.assignments a where a.id=assignment_id and public.is_teacher_of_class(a.classroom_id)));
create policy "submission student read own insert via api" on public.submissions for insert to authenticated with check(student_id=auth.uid() and exists(select 1 from public.assignments a where a.id=assignment_id and a.published and public.is_member_of_class(a.classroom_id)));
create policy "student reads own answers teacher reads class" on public.answers for select to authenticated using(exists(select 1 from public.submissions s join public.assignments a on a.id=s.assignment_id where s.id=submission_id and (s.student_id=auth.uid() or public.is_teacher_of_class(a.classroom_id))));
-- Writes to submissions/answers and answer_keys are performed by the JWT-validated Edge Function using service-role credentials.
create policy "class members read exercise media" on storage.objects for select to authenticated using(bucket_id='exercise-media' and (public.is_teacher_of_class((storage.foldername(name))[1]::uuid) or public.is_member_of_class((storage.foldername(name))[1]::uuid)));
create policy "class teacher or own student audio upload" on storage.objects for insert to authenticated with check(bucket_id='exercise-media' and ((public.is_teacher_of_class((storage.foldername(name))[1]::uuid) and (storage.filename(name) like 'teacher-'||auth.uid()||'-%')) or (public.is_member_of_class((storage.foldername(name))[1]::uuid) and storage.filename(name) like auth.uid()||'.%')));
create policy "teacher or own student audio update" on storage.objects for update to authenticated using(bucket_id='exercise-media' and ((public.is_teacher_of_class((storage.foldername(name))[1]::uuid) and storage.filename(name) like 'teacher-'||auth.uid()||'-%') or (public.is_member_of_class((storage.foldername(name))[1]::uuid) and storage.filename(name) like auth.uid()||'.%')));
create policy "teacher or own student audio delete" on storage.objects for delete to authenticated using(bucket_id='exercise-media' and ((public.is_teacher_of_class((storage.foldername(name))[1]::uuid) and storage.filename(name) like 'teacher-'||auth.uid()||'-%') or (public.is_member_of_class((storage.foldername(name))[1]::uuid) and storage.filename(name) like auth.uid()||'.%')));
-- Create a private bucket (audio only, max 20 MB per file).
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('exercise-media','exercise-media',false,20971520,array['audio/webm','audio/ogg','audio/mpeg','audio/mp4','audio/wav']) on conflict(id) do nothing;
